local util = require 'XLua.util'
local CoWait = CS.Engine.Lib.CoWait
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local RectTransform = CS.UnityEngine.RectTransform
------------ import ------------
------------ import ------------

------------ define ------------
local MaxCompound = 4
local TechnologyTipCellPath = 'Game.CatHouse.Handbook.CatHouseTechnologyTipCell'
------------ define ------------

---@class CatHouseTechnologyTips
---@field ClickArea                     	UnityEngine.RectTransform
---@field Group2                        	UnityEngine.RectTransform
---@field TxtTitle                      	UnityEngine.UI.Text
local CatHouseTechnologyTips = Class("CatHouseTechnologyTips")

function CatHouseTechnologyTips:__init()
    self.unitVo = nil ---合卡技
    self.skillVo = nil ----技能vo
end

function CatHouseTechnologyTips:__delete()
    self.controller = nil
end

function CatHouseTechnologyTips:Awake()
    if not isNull(self.ClickArea) then
        SetButtonAction(self.ClickArea, function()
            UIModule.BackDialog()
        end)
    end
    KTool.SetActive(self.Group2.gameObject, false)
    local argument = self.controller.Argument
    if not isNull(argument.parameters) then
        self.skillVo = argument.parameters.skillVo
        self.unitVo = argument.parameters.unitVo
    end
end

function CatHouseTechnologyTips:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.FillText(self.TxtTitle, self.skillVo.skillName)
        --合卡起始个数
        local _from = checkNumber(self.unitVo.startUnit)
        if _from < 1 then
            return
        end

        local contentGo = self.Group2.transform.parent.gameObject
        for i = _from, MaxCompound do
            local effectGo = contentGo.transform:Find("CellState"..i)
            if not effectGo then
                effectGo = CfUtils.InstantiateGo(self.Group2.gameObject, contentGo)
                effectGo.name = "CellState"..i
            end
            self:FillSkillEffect(effectGo, self.skillVo, i, self.unitVo)

            CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(effectGo.transform:GetComponent(typeof(RectTransform)))
        end
    end))
    return coWait
end

---FillSkillEffect
---@param go UnityEngine.GameObject
---@param skillVo UIBattlingSkillCardVo
---@param index number
---@param data UnitSkillVo
function CatHouseTechnologyTips:FillSkillEffect(go, skillVo, index, data)
    if not go or not skillVo then return end
    local desc
    if index == 2 then
        desc = skillVo.skillDesc_2
    elseif index == 3 then
        desc = skillVo.skillDesc_3
    elseif index == 4 then
        desc = skillVo.skillDesc_4
    end

    KTool.SetActive(go ,true)
    ---@type CatHouseTechnologyTipCell
    local nodeEnv = CfUtils.GetLuaScr(go.gameObject, TechnologyTipCellPath)
    if nodeEnv then
        nodeEnv:FreshUI(skillVo, index, data)
    end
end

function CatHouseTechnologyTips:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return CatHouseTechnologyTips